package com.intellitrack.service;
import com.intellitrack.entity.*;
import com.intellitrack.repository.*;
import com.intellitrack.controller.DeadlineAutomationController;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class DeadlineAutomationTest {
 @Test void enrollmentWelcomeCanBeDeliveredBeforeStudentCreatesAnAccount(){
  var google=mock(GoogleWorkspaceService.class);var connections=mock(GoogleConnectionRepository.class);var users=mock(UserRepository.class);var requirements=mock(DeliverableRepository.class);var enrollments=mock(StudentEnrollmentRepository.class);var emails=mock(DeadlineEmailRepository.class);var activity=mock(ActivityEmailService.class);
  var service=new DeadlineAutomationService(google,connections,users,requirements,enrollments,emails,mock(TrackingService.class),mock(SemesterService.class));ReflectionTestUtils.setField(service,"enabled",true);ReflectionTestUtils.setField(service,"activity",activity);
  var job=new DeadlineEmail();job.setId("welcome");job.setKind(ActivityEmailService.ENROLLMENT);job.setEnrollmentId(5L);
  when(google.deadlineMailConnected()).thenReturn(true);when(emails.findTop5ByStatusOrderByCreatedAtAsc("PENDING")).thenReturn(List.of(job));when(activity.handles(job)).thenReturn(true);when(activity.message(eq(job),isNull(),any())).thenReturn(Optional.of(new ActivityEmailService.Message("Welcome","Website link","student@example.test")));when(emails.claim(eq("welcome"),any())).thenReturn(1);
  service.run();verify(users,never()).findById(any());verify(google).sendDeadlineEmail("student@example.test","Welcome","Website link");assertEquals("SENT",job.getStatus());
 }
 @Test void calendarSyncRunsWhileEmailDeliveryIsDisabled(){
  var google=mock(GoogleWorkspaceService.class);var connections=mock(GoogleConnectionRepository.class);var users=mock(UserRepository.class);var requirements=mock(DeliverableRepository.class);var enrollments=mock(StudentEnrollmentRepository.class);var emails=mock(DeadlineEmailRepository.class);
  var service=new DeadlineAutomationService(google,connections,users,requirements,enrollments,emails,mock(TrackingService.class),mock(SemesterService.class));ReflectionTestUtils.setField(service,"calendarEnabled",true);
  var connection=new GoogleConnection();connection.setId("1:calendar");connection.setUserId(1L);connection.setPurpose("calendar");connection.setEncryptedRefreshToken("encrypted");
  var user=new User();user.setId(1L);user.setRole("coordinator");when(users.findById(1L)).thenReturn(Optional.of(user));when(connections.findAll()).thenReturn(List.of(connection));when(connections.findById(connection.getId())).thenReturn(Optional.of(connection));
  service.run();verify(google).syncDeadlines(eq(user),eq(List.of()));verifyNoInteractions(emails);verify(google,never()).sendDeadlineEmail(any(),any(),any());
 }
 @Test void requirementChangesDeduplicateRecipientsAndJobs(){
  var google=mock(GoogleWorkspaceService.class);var connections=mock(GoogleConnectionRepository.class);var users=mock(UserRepository.class);var requirements=mock(DeliverableRepository.class);var enrollments=mock(StudentEnrollmentRepository.class);var emails=mock(DeadlineEmailRepository.class);var service=new DeadlineAutomationService(google,connections,users,requirements,enrollments,emails,mock(TrackingService.class),mock(SemesterService.class));ReflectionTestUtils.setField(service,"enabled",true);
  var subject=new Subject();subject.setId(1L);var section=new ClassSection();section.setSubject(subject);section.setAcademicTerm("2026-2027 / 1");var student=new User();student.setId(10L);var enrollment=new StudentEnrollment();enrollment.setClassSection(section);enrollment.setStudent(student);var d=new Deliverable();d.setId(2L);d.setName("Proposal");d.setSubject(subject);d.setAcademicTerm(section.getAcademicTerm());when(requirements.findById(2L)).thenReturn(Optional.of(d));when(enrollments.findAllWithSectionAndSubject()).thenReturn(List.of(enrollment,enrollment));var ids=new HashSet<String>();when(emails.existsById(anyString())).thenAnswer(i->ids.contains(i.getArgument(0)));when(emails.save(any())).thenAnswer(i->{DeadlineEmail job=i.getArgument(0);ids.add(job.getId());return job;});
  service.changed(new DeadlineAutomationService.RequirementChanged(2L,"New requirement"));service.changed(new DeadlineAutomationService.RequirementChanged(2L,"New requirement"));verify(emails,times(1)).save(any());verify(google,never()).sendDeadlineEmail(any(),any(),any());
 }
 @Test void reminderWindows(){var now=LocalDateTime.of(2026,10,23,12,0);assertNull(DeadlineAutomationService.reminder(now.plusDays(2),now));assertEquals("Due within 24 hours",DeadlineAutomationService.reminder(now.plusHours(2),now));assertEquals("Due within one hour",DeadlineAutomationService.reminder(now.plusMinutes(30),now));assertEquals("Overdue",DeadlineAutomationService.reminder(now.minusSeconds(1),now));}
 @Test void changedDeadlineHasDifferentRevision(){var d=new Deliverable();d.setName("Proposal");d.setDueAt(LocalDateTime.of(2026,10,23,12,0));String first=DeadlineAutomationService.revision(d);assertEquals(first,DeadlineAutomationService.revision(d));d.setDueAt(d.getDueAt().plusHours(1));assertNotEquals(first,DeadlineAutomationService.revision(d));}
 @Test void triggerRequiresStrongMatchingSecret(){var service=mock(DeadlineAutomationService.class);var controller=new DeadlineAutomationController(service);assertThrows(ResponseStatusException.class,()->controller.trigger(""));ReflectionTestUtils.setField(controller,"secret","x".repeat(32));assertThrows(ResponseStatusException.class,()->controller.trigger("wrong"));verifyNoInteractions(service);controller.trigger("x".repeat(32));verify(service).run();}
 @Test void disabledWorkerDoesNotSendOrQuery(){var google=mock(GoogleWorkspaceService.class);var connections=mock(GoogleConnectionRepository.class);var users=mock(UserRepository.class);var requirements=mock(DeliverableRepository.class);var enrollments=mock(StudentEnrollmentRepository.class);var emails=mock(DeadlineEmailRepository.class);var tracking=mock(TrackingService.class);var semesters=mock(SemesterService.class);var service=new DeadlineAutomationService(google,connections,users,requirements,enrollments,emails,tracking,semesters);service.run();service.changed(new DeadlineAutomationService.RequirementChanged(1L,"New requirement"));verifyNoInteractions(google,connections,users,requirements,enrollments,emails,tracking,semesters);}
 @Test void invalidatedQueuedEmailIsCancelled(){var google=mock(GoogleWorkspaceService.class);var connections=mock(GoogleConnectionRepository.class);var users=mock(UserRepository.class);var requirements=mock(DeliverableRepository.class);var enrollments=mock(StudentEnrollmentRepository.class);var emails=mock(DeadlineEmailRepository.class);var tracking=mock(TrackingService.class);var semesters=mock(SemesterService.class);var service=new DeadlineAutomationService(google,connections,users,requirements,enrollments,emails,tracking,semesters);ReflectionTestUtils.setField(service,"enabled",true);var job=new DeadlineEmail();job.setId("job");job.setUserId(1L);job.setRequirementId(2L);job.setKind("Overdue");when(google.deadlineMailConnected()).thenReturn(true);when(emails.findTop5ByStatusOrderByCreatedAtAsc("PENDING")).thenReturn(List.of(job));service.run();assertEquals("CANCELLED",job.getStatus());verify(google,never()).sendDeadlineEmail(any(),any(),any());}
}
